import {money,number,revenueModel,quartiles,percentile,normalizedScore,sensitivity,decisionGate} from './calculations.js';

const fixtures=[
 {id:'meal',idea:'Meal Planner Template',keyword:'meal planner printable',category:'Digital planners',price:14,targetRevenue:1500,targetProfit:900,margin:.78,conversion:.024,adSpend:120,fixedCosts:35,variableCosts:0,demand:5400,listings:18400,confidence:'Low–medium',prices:[3,5,7,8,9,10,11,12,14,14,15,16,18,19,22,24,28,34],trend:[3100,3500,3800,4200,4600,5400],compTrend:[16500,16900,17300,17700,18100,18400],scores:{demand:62,competition:38,pricing:71,differentiation:68,scalability:75,production:80},reviews:[12,18,25,30,45,62,75,88,110,145,190,260,350,470,620,850,1100,1560]},
 {id:'wedding',idea:'Editable Wedding Budget',keyword:'wedding budget spreadsheet',category:'Spreadsheets',price:18,targetRevenue:1800,targetProfit:1100,margin:.82,conversion:.019,adSpend:160,fixedCosts:35,variableCosts:0,demand:3200,listings:8900,confidence:'Low',prices:[6,8,9,11,12,14,15,16,17,18,20,22,24,26,29,32],trend:[2100,2250,2450,2650,2900,3200],compTrend:[7900,8100,8300,8500,8700,8900],scores:{demand:54,competition:53,pricing:78,differentiation:60,scalability:76,production:72},reviews:[8,15,20,24,40,57,66,72,90,130,160,230,390,500,670,980]},
 {id:'kids',idea:'Kids Chore Chart Kit',keyword:'chore chart printable',category:'Printables',price:9,targetRevenue:1200,targetProfit:650,margin:.72,conversion:.027,adSpend:90,fixedCosts:20,variableCosts:0,demand:7100,listings:22100,confidence:'Low–medium',prices:[2,3,4,5,5,6,7,8,8,9,10,11,12,14,16,19],trend:[4400,4800,5100,5900,6500,7100],compTrend:[20100,20500,21100,21600,21900,22100],scores:{demand:76,competition:31,pricing:55,differentiation:63,scalability:71,production:87},reviews:[5,10,16,23,31,45,55,67,74,101,126,176,260,420,630,870]}
];
const defaults={weights:{demand:25,competition:20,pricing:20,differentiation:15,scalability:10,production:10},gate:{signalMin:55,burdenMax:65}};
let state=JSON.parse(localStorage.getItem('market-lens-state')||'null')||{products:fixtures,active:'meal',view:'overview',weights:defaults.weights};
state.gate={...defaults.gate,...state.gate};
const $=s=>document.querySelector(s); const fmtPct=v=>`${(v*100).toFixed(1)}%`; const active=()=>state.products.find(p=>p.id===state.active)||state.products[0];
function save(){localStorage.setItem('market-lens-state',JSON.stringify(state));}
function chartLine(data,color='#3368e8'){const max=Math.max(...data)*1.12;const pts=data.map((v,i)=>`${i*(100/(data.length-1))},${100-v/max*100}`).join(' ');return `<div class="chart-wrap"><svg class="line-svg" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline fill="none" stroke="${color}" stroke-width="2" points="${pts}"/><circle cx="100" cy="${100-data.at(-1)/max*100}" r="2.5" fill="${color}"/></svg></div>`}
function card(title,meta,inside,cls=''){return `<article class="card ${cls}"><h2>${title}</h2><div class="meta">${meta}</div>${inside}</article>`}
function decisionPanel(p){const g=decisionGate(p,state.gate),tone=g.pass?(g.lowEvidence?'validate':'go'):'nogo';return `<section class="decision-panel ${tone}"><div class="decision-state"><span>DECISION GATE</span><strong>${g.status}</strong><p>${g.reasons[0]}</p></div><div class="gate-metric"><div><span>Market signal</span><b>${g.signal}</b><small>PASS ≥ ${state.gate.signalMin}</small></div><div class="gate-track high"><i style="width:${g.signal}%"></i><em style="left:${state.gate.signalMin}%"></em></div><p>45% demand · 35% competitive opening · 20% price/margin fit</p></div><div class="gate-metric"><div><span>Execution burden</span><b>${g.burden}</b><small>PASS ≤ ${state.gate.burdenMax}</small></div><div class="gate-track low"><i style="width:${g.burden}%"></i><em style="left:${state.gate.burdenMax}%"></em></div><p>50% traffic coverage · 30% competition · 20% margin drag</p></div><div class="gate-controls"><label>Signal gate <input data-gate="signalMin" type="number" min="0" max="100" value="${state.gate.signalMin}"></label><label>Burden gate <input data-gate="burdenMax" type="number" min="0" max="100" value="${state.gate.burdenMax}"></label></div></section>`}
function overview(p){const q=quartiles(p.prices),ratio=p.demand/p.listings,m=revenueModel(p);return `${decisionPanel(p)}
<div class="grid kpis">
${kpi('Est. monthly search demand',number(p.demand),'User-supplied fixture · monthly')}${kpi('Competing listings',number(p.listings),'Fixture observation')}${kpi('Demand / competition',ratio.toFixed(2),'Derived · lower is crowded')}${kpi('Median competitor price',money(q.median),`P25 ${money(q.p25)} · P75 ${money(q.p75)}`)}${kpi('Revenue model orders',number(m.requiredOrders),'Orders / month needed')}
</div><div class="grid charts">${card('Search demand over time','Synthetic 6-month research fixture',chartLine(p.trend))}${card('Listing supply trend','Synthetic observation series',chartLine(p.compTrend,'#df8b22'))}${card('Competitor price distribution','Manual fixture · 18 observed listings',histogram(p.prices,p.price))}</div>
<div class="grid split"><article class="card"><h2>Evidence ledger</h2><div class="meta">Every metric retains its origin and caveat</div><table class="table"><thead><tr><th>Metric</th><th>Value</th><th>Source / method</th><th>Confidence</th></tr></thead><tbody><tr><td>Search demand</td><td class="value">${number(p.demand)} / mo</td><td><span class="source">Synthetic fixture</span> User-editable assumption</td><td>Low</td></tr><tr><td>Competition</td><td class="value">${number(p.listings)}</td><td><span class="source">Synthetic fixture</span> Keyword-scope count</td><td>Low</td></tr><tr><td>Price set</td><td class="value">${p.prices.length} listings</td><td><span class="source">Manual fixture</span> illustrative observations</td><td>Medium</td></tr><tr><td>Monthly sales</td><td class="value">N/A</td><td>Unsupported — no permitted provider attached</td><td>—</td></tr></tbody></table></article>${card('Market read','Quantified, not a recommendation',`<table class="table"><tbody><tr><td>Concentration</td><td><span class="pill">Moderate</span></td></tr><tr><td>Seasonality</td><td>Not measured</td></tr><tr><td>Addressable market denominator</td><td>N/A</td></tr><tr><td>Market share calculation</td><td>N/A — no supported denominator</td></tr></tbody></table><div class="notice">Review counts and listing volume are not treated as sales. Connect a permitted provider or replace the fixture with documented observations.</div>`)}</div>`}
function kpi(label,value,detail){return `<article class="kpi"><span class="label">${label}</span><strong>${value}</strong><small>${detail}</small></article>`}
function histogram(prices,target){const bins=[0,5,10,15,20,25,30,35];let counts=bins.slice(0,-1).map((b,i)=>prices.filter(x=>x>=b&&x<bins[i+1]).length);const max=Math.max(...counts);return `<div class="chart-wrap"><div class="bars">${counts.map((c,i)=>`<div class="bar" style="height:${Math.max(6,c/max*100)}%"><em>$${bins[i]}–${bins[i+1]}</em></div>`).join('')}</div></div><div class="provenance"><span class="source">Target: ${money(target)}</span><span>● proposed price</span></div>`}
function positioning(p){const pct=percentile(p.price,p.prices),q=quartiles(p.prices);return `<div class="grid kpis">${kpi('Target price',money(p.price),'User assumption')}${kpi('Price percentile',pct?`${pct.toFixed(0)}th`:'N/A','Versus fixture listings')}${kpi('Observed median',money(q.median),'Manual fixture')}${kpi('P25 / P75',`${money(q.p25)} / ${money(q.p75)}`,'Observed distribution')}${kpi('Price distance',money(p.price-q.median),'Target vs median')}</div><div class="grid split">${card('Price placement','Fixture distribution',histogram(p.prices,p.price))}${card('Competitive positioning','Filters reflect current research scope',`<table class="table"><tbody><tr><td>Category</td><td>${p.category}</td></tr><tr><td>Keyword relevance</td><td>Primary keyword</td></tr><tr><td>Listing type</td><td>Digital only</td></tr><tr><td>Recent review activity</td><td>N/A — no time series</td></tr><tr><td>Listing age</td><td>N/A — no source</td></tr></tbody></table>`)}</div>${card('Price versus review-count scatter','Synthetic competitor rows — reviews are signals of visibility, not sales',scatter(p),'chart')}`}
function scatter(p){const maxR=Math.max(...p.reviews);return `<div class="chart-wrap"><svg class="line-svg" viewBox="0 0 100 100" preserveAspectRatio="none">${p.prices.map((price,i)=>`<circle cx="${5+i*90/(p.prices.length-1)}" cy="${94-p.reviews[i]/maxR*83}" r="2.3" fill="#3368e8" opacity=".75"/>`).join('')}<line x1="${Math.min(95,p.price/35*100)}" y1="4" x2="${Math.min(95,p.price/35*100)}" y2="96" stroke="#df8b22" stroke-dasharray="3 3"/></svg></div><div class="provenance">x = price · y = review count · orange = target price</div>`}
function feasibility(p){let m=revenueModel(p);const scenarios=[['Pessimistic',{price:p.price*.85,conversion:p.conversion*.7,margin:p.margin-.08}],['Base',p],['Optimistic',{price:p.price*1.12,conversion:p.conversion*1.25,margin:p.margin+.04}]];return `<div class="grid kpis">${kpi('Required monthly orders',m.requiredOrders?number(m.requiredOrders):'Infeasible','Max revenue / profit need')}${kpi('Required daily orders',m.dailyOrders?m.dailyOrders.toFixed(1):'N/A','30-day month')}${kpi('Required monthly visits',m.visits?number(m.visits):'N/A',`At ${fmtPct(p.conversion)} CVR`) }${kpi('Contribution / order',money(m.contribution),`${(p.margin*100).toFixed(0)}% contribution margin`) }${kpi('Break-even volume',m.breakEven?number(m.breakEven):'Infeasible',`Fixed costs ${money(p.fixedCosts)}`)}</div><div class="grid split">${card('Scenario model','Pessimistic, base, optimistic assumptions',`<div class="scenario">${scenarios.map(([name,vals])=>{let x=revenueModel({...p,...vals});return `<article class="${name==='Base'?'base':''}"><small class="muted">${name.toUpperCase()}</small><strong>${x.requiredOrders?number(x.requiredOrders):'N/A'} orders</strong><div class="muted">${x.visits?number(x.visits):'N/A'} visits · ${money(x.contribution)} contribution</div></article>`}).join('')}</div><div class="notice">${m.feasible?'Contribution remains positive; test pricing against actual fees and conversion evidence.':'Contribution is zero or negative. This scenario cannot meet a profit target.'}</div>`) }${card('Revenue sensitivity','Price against required order volume',sensitivity(p).map(r=>`<div class="range"><label>${money(r.price)}</label><div class="score"><b style="width:${Math.min(100,((r.orders||0)/Math.max(...sensitivity(p).map(x=>x.orders||0)))*100)}%"></b></div><span>${r.orders?number(r.orders):'N/A'}</span></div>`).join(''))}</div>`}
function comparison(){const ranks=state.products.map(p=>({p,score:normalizedScore(p.scores,state.weights),gate:decisionGate(p,state.gate)})).sort((a,b)=>b.score-a.score);return `${card('Weighted opportunity comparison','Decision gate is threshold-based; score is for ranking',`<table class="table"><thead><tr><th>Rank</th><th>Hypothesis</th><th>Decision</th><th>Signal / burden</th><th>Opportunity score</th><th>Evidence</th></tr></thead><tbody>${ranks.map((r,i)=>`<tr><td class="rank">${i+1}</td><td><b>${r.p.idea}</b><br/><span class="muted">${r.p.keyword}</span></td><td><span class="decision-chip ${r.gate.pass?'pass':'fail'}">${r.gate.status}</span></td><td><b>${r.gate.signal}</b> / ${r.gate.burden}<br/><span class="muted">high / low</span></td><td><div class="value">${r.score.toFixed(0)} / 100</div><div class="score"><b style="width:${r.score}%"></b></div></td><td><span class="pill">${r.p.confidence}</span></td></tr>`).join('')}</tbody></table>`)}<div class="grid split">${card('Scoring weights','Adjustable; automatically normalized',Object.entries(state.weights).map(([k,v])=>`<div class="range"><label>${k[0].toUpperCase()+k.slice(1)}</label><input data-weight="${k}" type="range" min="0" max="40" value="${v}"><span>${v}%</span></div>`).join(''))}${card('Score composition','Base product factors (0–100)',radar(active()))}</div>`}
function radar(p){return `<table class="table"><tbody>${Object.entries(p.scores).map(([k,v])=>`<tr><td>${k}</td><td style="width:58%"><div class="score"><b style="width:${v}%"></b></div></td><td>${v}</td></tr>`).join('')}</tbody></table><div class="notice">A higher score is not evidence of market demand. Compare it with the confidence field before prioritizing research.</div>`}
function sensitivityView(p){return `<div class="grid split">${card('One-variable sensitivity','Move assumptions; values update immediately',range('Product price','price',p.price,3,50,1,'$')+range('Conversion rate','conversion',p.conversion,.005,.1,.001,'%')+range('Contribution margin','margin',p.margin,.1,.95,.01,'%')+range('Advertising spend','adSpend',p.adSpend,0,600,10,'$'))}${card('Threshold outputs','Derived from current inputs',thresholds(p))}</div><div class="grid split">${card('Price × conversion heatmap','Required monthly visits (model-derived)',heatmap(p))}${card('Scenario integrity','Data and statistical limits',`<table class="table"><tbody><tr><td>Search-volume assumption</td><td>${number(p.demand)} / mo</td></tr><tr><td>Market capture rate</td><td>N/A — denominator unsupported</td></tr><tr><td>Competition pressure</td><td>Manual qualitative input</td></tr><tr><td>Monte Carlo</td><td>Disabled — no validated distributions supplied</td></tr></tbody></table><div class="notice">The model deliberately does not invent probability distributions or market-share denominators.</div>`)}</div>`}
function range(label,key,val,min,max,step,prefix){let display=key==='conversion'||key==='margin'?fmtPct(val):prefix+val;return `<div class="range"><label>${label}</label><input data-param="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}"><span>${display}</span></div>`}
function thresholds(p){let m=revenueModel(p);return `<table class="table"><tbody><tr><td>Contribution/order</td><td class="value">${money(m.contribution)}</td></tr><tr><td>Orders for revenue goal</td><td class="value">${m.orders?number(m.orders):'N/A'}</td></tr><tr><td>Orders for profit goal</td><td class="value">${m.profitOrderCount?number(m.profitOrderCount):'Infeasible'}</td></tr><tr><td>Daily traffic needed</td><td class="value">${m.visits?number(m.visits/30):'N/A'}</td></tr></tbody></table>`}
function heatmap(p){let cvrs=[.01,.02,.03,.04,.05],prices=[p.price*.7,p.price*.85,p.price,p.price*1.15,p.price*1.3];return `<div class="heatmap"><div></div>${cvrs.map(v=>`<div>${fmtPct(v)}</div>`).join('')}${prices.map(pr=>`<div>${money(pr)}</div>${cvrs.map(c=>{let v=revenueModel({...p,price:pr,conversion:c}).visits;return `<div>${v?number(v):'—'}</div>`}).join('')}`).join('')}</div>`}
function renderInputs(p){$('#inputs').innerHTML=`<label>Product idea<input data-field="idea" value="${p.idea}"></label><label>Primary keyword<input data-field="keyword" value="${p.keyword}"></label><label>Category<select data-field="category">${['Digital planners','Spreadsheets','Printables','Templates'].map(x=>`<option ${x===p.category?'selected':''}>${x}</option>`).join('')}</select></label><label>Revenue target<input data-field="targetRevenue" type="number" value="${p.targetRevenue}"></label><label>Profit target<input data-field="targetProfit" type="number" value="${p.targetProfit}"></label>`}
function render(){const p=active();$('#ideaTitle').textContent=p.idea;$('#keywordSub').textContent=`Keyword: ${p.keyword} · ${p.category}`;$('#confidence').textContent=p.confidence;$('#timestamp').textContent=`Saved ${new Date().toLocaleDateString()}`;$('#hypothesisList').innerHTML=state.products.map(x=>{const g=decisionGate(x,state.gate);return `<button class="hypothesis ${x.id===p.id?'active':''}" data-product="${x.id}"><i class="${g.pass?'pass':'fail'}"></i>${x.idea}</button>`}).join('');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));renderInputs(p);let views={overview,positioning,feasibility,comparison,sensitivity:sensitivityView};$('#content').innerHTML=views[state.view](p); bind();}
function bind(){document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{state.active=b.dataset.product;save();render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;save();render()});document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{let p=active(),key=el.dataset.field;p[key]=el.type==='number'?+el.value:el.value;save();render()});document.querySelectorAll('[data-param]').forEach(el=>el.oninput=()=>{active()[el.dataset.param]=+el.value;save();render()});document.querySelectorAll('[data-weight]').forEach(el=>el.oninput=()=>{state.weights[el.dataset.weight]=+el.value;save();render()});document.querySelectorAll('[data-gate]').forEach(el=>el.oninput=()=>{state.gate[el.dataset.gate]=Math.max(0,Math.min(100,+el.value));save();render()});}
$('#addHypothesis').onclick=()=>{let p=structuredClone(active());p.id='p'+Date.now();p.idea='New product hypothesis';p.keyword='new keyword';state.products.push(p);state.active=p.id;save();render()};$('#export').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='market-lens-research.json';a.click();URL.revokeObjectURL(a.href)};render();
